CREATE TABLE "User" ("id" TEXT NOT NULL, "username" TEXT NOT NULL, "passwordHash" TEXT NOT NULL DEFAULT '', "role" TEXT NOT NULL DEFAULT 'ADMIN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE TABLE "DigiposAccount" ("id" TEXT NOT NULL, "username" TEXT NOT NULL, "userCode" TEXT NOT NULL, "outletId" TEXT NOT NULL, "phoneMasked" TEXT NOT NULL, "status" TEXT NOT NULL, "validUntil" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DigiposAccount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "UserAccountAccess" ("userId" TEXT NOT NULL, "accountId" TEXT NOT NULL, CONSTRAINT "UserAccountAccess_pkey" PRIMARY KEY ("userId", "accountId"));
CREATE TABLE "Transaction" ("id" TEXT NOT NULL, "digiposAccountId" TEXT NOT NULL, "createdById" TEXT NOT NULL, "transactionType" TEXT NOT NULL, "mode" TEXT NOT NULL, "status" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "requestId" TEXT NOT NULL, "sanitizedInput" JSONB NOT NULL, "normalizedResponse" JSONB, "errorCode" TEXT, "errorMessage" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Transaction_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Transaction_idempotencyKey_key" ON "Transaction"("idempotencyKey");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "actorId" TEXT, "action" TEXT NOT NULL, "resource" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Session" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "IdempotencyRecord" ("key" TEXT NOT NULL, "userId" TEXT NOT NULL, "response" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IdempotencyRecord_pkey" PRIMARY KEY ("key"));
CREATE INDEX "IdempotencyRecord_expiresAt_idx" ON "IdempotencyRecord"("expiresAt");
CREATE TABLE "Batch" ("id" TEXT NOT NULL, "accountId" TEXT NOT NULL, "transactionType" TEXT NOT NULL, "status" TEXT NOT NULL, "mode" TEXT NOT NULL, "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "claimedAt" TIMESTAMP(3), "claimedBy" TEXT, CONSTRAINT "Batch_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BatchItem" ("id" TEXT NOT NULL, "batchId" TEXT NOT NULL, "rowNumber" INTEGER NOT NULL, "serial" TEXT NOT NULL, "normalizedSerial" TEXT NOT NULL, "status" TEXT NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "response" JSONB, "errorCode" TEXT, "errorMessage" TEXT, "responseCode" TEXT, "responseMessage" TEXT, "providerReference" TEXT, "requestId" TEXT, "idempotencyKey" TEXT, "startedAt" TIMESTAMP(3), "finishedAt" TIMESTAMP(3), CONSTRAINT "BatchItem_pkey" PRIMARY KEY ("id"));
CREATE INDEX "BatchItem_batchId_status_idx" ON "BatchItem"("batchId", "status");
ALTER TABLE "UserAccountAccess" ADD CONSTRAINT "UserAccountAccess_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "UserAccountAccess" ADD CONSTRAINT "UserAccountAccess_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "DigiposAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Transaction" ADD CONSTRAINT "Transaction_digiposAccountId_fkey" FOREIGN KEY ("digiposAccountId") REFERENCES "DigiposAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Transaction" ADD CONSTRAINT "Transaction_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Batch" ADD CONSTRAINT "Batch_accountId_fkey" FOREIGN KEY ("accountId") REFERENCES "DigiposAccount"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Batch" ADD CONSTRAINT "Batch_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "BatchItem" ADD CONSTRAINT "BatchItem_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "Batch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "IntegrationConfig" ("id" TEXT NOT NULL, "requestedMode" TEXT NOT NULL DEFAULT 'MOCK', "approvedMode" TEXT NOT NULL DEFAULT 'MOCK', "baseUrl" TEXT NOT NULL DEFAULT '', "apiPath" TEXT NOT NULL DEFAULT '/api/bulk-sellout', "timeoutMs" INTEGER NOT NULL DEFAULT 30000, "maxRetries" INTEGER NOT NULL DEFAULT 2, "concurrency" INTEGER NOT NULL DEFAULT 1, "version" INTEGER NOT NULL DEFAULT 1, "updatedById" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "IntegrationConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IntegrationSecret" ("id" TEXT NOT NULL, "configId" TEXT NOT NULL, "ciphertext" TEXT NOT NULL, "updatedById" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IntegrationSecret_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IntegrationSecret_configId_key" ON "IntegrationSecret"("configId");
CREATE TABLE "ConfigAuditLog" ("id" TEXT NOT NULL, "configId" TEXT NOT NULL, "actorId" TEXT, "action" TEXT NOT NULL, "changedFields" JSONB NOT NULL, "ipAddress" TEXT, "requestId" TEXT NOT NULL, "reason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ConfigAuditLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ConfigAuditLog_configId_createdAt_idx" ON "ConfigAuditLog"("configId", "createdAt");
ALTER TABLE "IntegrationSecret" ADD CONSTRAINT "IntegrationSecret_configId_fkey" FOREIGN KEY ("configId") REFERENCES "IntegrationConfig"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ConfigAuditLog" ADD CONSTRAINT "ConfigAuditLog_configId_fkey" FOREIGN KEY ("configId") REFERENCES "IntegrationConfig"("id") ON DELETE CASCADE ON UPDATE CASCADE;
